import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;

class OrderCancellationMailTest {

    record Sent(String address, String subject, String body) {
    }

    static class RecordingTransport implements MailTransport {
        final List<Sent> sent = new ArrayList<>();

        @Override
        public void deliver(String address, String subject, String body) {
            sent.add(new Sent(address, subject, body));
        }
    }

    @Test
    void cancellingAnOrderMailsTheCustomerExactlyOnce() {
        RecordingTransport mail = new RecordingTransport();
        try (var shop = new AnnotationConfigApplicationContext()) {
            shop.register(ShopConfig.class);
            shop.registerBean(MailTransport.class, () -> mail, bd -> bd.setPrimary(true));
            shop.refresh();

            OrderFacade orders = shop.getBean(OrderFacade.class);
            shop.getBean(CustomerFacade.class).register("c-1", "anna@shop.example");

            String id = orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));
            orders.cancel(id);
            orders.cancel(id);

            assertEquals(1, mail.sent.size());
            Sent sent = mail.sent.getFirst();
            assertEquals("anna@shop.example", sent.address());
            assertEquals(true, sent.subject().contains(id));
        }
    }

    @Test
    void aNotCancelledOrderSendsNoCancellationMail() {
        RecordingTransport mail = new RecordingTransport();
        try (var shop = new AnnotationConfigApplicationContext()) {
            shop.register(ShopConfig.class);
            shop.registerBean(MailTransport.class, () -> mail, bd -> bd.setPrimary(true));
            shop.refresh();

            OrderFacade orders = shop.getBean(OrderFacade.class);
            shop.getBean(CustomerFacade.class).register("c-1", "anna@shop.example");
            orders.place("c-1", Money.pln(1000), Instant.parse("2026-10-01T10:00:00Z"));

            assertEquals(0, mail.sent.size());
        }
    }
}
